// Producer:
kafkaTemplate.send("pedidos-criados", pedido.id().toString(), pedido);

// Consumer:
@KafkaListener(topics = "pedidos-criados", groupId = "notificacoes")
public void consumir(PedidoEvento evento) {
    System.out.println("Recebido: " + evento.id());
}

